constructor(ctx, config = {}) {
  this.ctx = ctx;
  this.config = config;
  // 2026-10-11: follow DSH_HOME before falling back to ~/.dsh, so a portable/isolated
  // install does not read or write the user's default home (same convention as
  // huahua-dsh-chatroom). Without this, a portable instance shares dsh-weave state
  // with the default-home instance.
  const weaveHome = process.env.DSH_HOME || join(homedir(), ".dsh");
  this.identityPath = config.identityPath ?? join(weaveHome, "dsh-weave", "identity.json");
  this.peersPath = config.peersPath ?? join(weaveHome, "dsh-weave", "peers.json");
  this.hostName = config.hostName ?? hostname();
  this.endpoint = undefined;
  this.starting = undefined;

